def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number where fib(0)=0, fib(1)=1."""
    if n < 1: 
        return 0
    elif n == 1: 
        return 1
    else: 
        return fibonacci(n-1) + fibonacci(n-2)

