    """Return a new sorted copy of arr using bubble sort."""
    # Traverse through all array
    for i in range(len(arr) - 1):
        for j in range(len(arr) - i - 1):
            # Swap if element found is greater
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

