def merge_dicts(d1: dict, d2: dict) -> dict:
    """Merge two dictionaries, d2 values overriding d1 on conflict."""
    result = {}
    for key, value in d1.items():
        result[key] = value
    for key, value in d2.items():
        result[key] = value
    return result

